INSERT INTO courses (id, title, description, template_style, estimated_duration_minutes, category_id, status, certificate_enabled, passing_score)
INSERT INTO course_modules (id, course_id, title, description, sort_order) VALUES
('a1000001-0001-0001-0001-000000000001', 'c1000001-aabb-bbcc-ccdd-000000000001', 'Legal Framework & Employer/Employee Duties', 'Understand the key UK health and safety legislation and your legal responsibilities.', 1),
('a1000002-0001-0002-0001-000000000001', 'c1000001-aabb-bbcc-ccdd-000000000001', 'Hazard Identification & Risk Assessment', 'Learn to identify common retail hazards and apply the HSE 5-step risk assessment process.', 2),
('a1000003-0001-0003-0001-000000000001', 'c1000001-aabb-bbcc-ccdd-000000000001', 'Fire Safety, First Aid & Incident Reporting', 'Know the fire safety procedures, first aid responsibilities, and how to report incidents under RIDDOR.', 3);
INSERT INTO course_lessons (id, module_id, title, sort_order, estimated_duration_minutes, content) VALUES
('b1010001-0001-0001-0001-000000000001', 'a1000001-0001-0001-0001-000000000001', 'The Health and Safety at Work Act 1974', 1, 5, '[{"type":"image","url":"/elearning/hs-course-hero.jpg","content":"Workplace Health & Safety — UK Retail Training"},{"type":"heading","content":"The Health and Safety at Work Act 1974 (HSWA)"},{"type":"paragraph","content":"The HSWA is the primary piece of UK legislation governing workplace health and safety. It places a general duty on employers to ensure, so far as is reasonably practicable, the health, safety and welfare of all their employees while at work."},{"type":"infobox","content":"The HSWA applies to every workplace in the UK, including retail stores, warehouses, offices, and forecourts. It is enforced by the Health and Safety Executive (HSE) and local authorities."},{"type":"subheading","content":"Key Provisions of the Act"},{"type":"bullet_points","items":["Section 2 — General duties of employers to employees: provide safe systems of work, safe equipment, adequate training, and a written safety policy (if 5+ employees)","Section 3 — Duty to non-employees: employers must ensure their activities do not put customers, visitors, or contractors at risk","Section 7 — Employee duties: take reasonable care of yourself and others, cooperate with your employer on safety matters","Section 8 — Do not intentionally or recklessly interfere with anything provided for health and safety","Section 33 — Offences: failure to comply can result in unlimited fines and up to 2 years imprisonment"]},{"type":"highlight","content":"Every retail employee has a legal duty under Section 7 of the HSWA to take reasonable care for their own safety and the safety of others who may be affected by their actions at work."},{"type":"subheading","content":"Supporting Regulations"},{"type":"paragraph","content":"The HSWA is supported by numerous sets of regulations, including:"},{"type":"bullet_points","items":["Management of Health and Safety at Work Regulations 1999 — requires employers to carry out risk assessments","Workplace (Health, Safety and Welfare) Regulations 1992 — covers ventilation, temperature, lighting, cleanliness, and facilities","Personal Protective Equipment at Work Regulations 2022 — PPE must be provided free of charge where risks cannot be eliminated","Health and Safety (Display Screen Equipment) Regulations 1992 — for staff using computers or tills for prolonged periods"]},{"type":"note","content":"Your employer must display the official HSE Health and Safety Law poster, or provide each employee with the equivalent leaflet."}]'::jsonb),
INSERT INTO course_assessments (id, course_id, title, passing_score, max_attempts, time_limit_minutes) VALUES
('d1000001-0001-0001-0001-000000000001', 'c1000001-aabb-bbcc-ccdd-000000000001', 'Workplace Health & Safety Assessment', 70, 3, 15);
INSERT INTO assessment_questions (assessment_id, question_text, question_type, options, correct_answer, explanation, points, sort_order) VALUES
('d1000001-0001-0001-0001-000000000001', 'What is the primary piece of UK health and safety legislation?', 'multiple_choice', '["Health and Safety at Work Act 1974","Regulatory Reform (Fire Safety) Order 2005","RIDDOR 2013","Management of Health and Safety at Work Regulations 1999"]'::jsonb, '"Health and Safety at Work Act 1974"'::jsonb, 'The HSWA 1974 is the overarching framework for workplace health and safety in the UK.', 10, 1),
('d1000001-0001-0001-0001-000000000001', 'Under Section 7 of the HSWA, employees have a duty to:', 'multiple_choice', '["Carry out risk assessments","Take reasonable care for their own safety and that of others","Provide PPE to colleagues","Write the company safety policy"]'::jsonb, '"Take reasonable care for their own safety and that of others"'::jsonb, 'Section 7 places a duty on employees to take reasonable care.', 10, 2),
('d1000001-0001-0001-0001-000000000001', 'What is the single largest cause of workplace injury in UK retail?', 'multiple_choice', '["Manual handling","Slips, trips, and falls","Workplace violence","Electrical hazards"]'::jsonb, '"Slips, trips, and falls"'::jsonb, 'HSE data: slips, trips and falls account for over 30% of all reported retail injuries.', 10, 3),
('d1000001-0001-0001-0001-000000000001', 'How many steps are in the HSE risk assessment process?', 'multiple_choice', '["3","4","5","6"]'::jsonb, '"5"'::jsonb, 'The HSE recommends a 5-step approach.', 10, 4),
('d1000001-0001-0001-0001-000000000001', 'Employers must provide PPE free of charge to employees.', 'true_false', '["True","False"]'::jsonb, '"True"'::jsonb, 'Under the PPE at Work Regulations 2022, PPE must be provided free of charge.', 10, 5),
('d1000001-0001-0001-0001-000000000001', 'What does the P in the PASS fire extinguisher technique stand for?', 'multiple_choice', '["Push","Pull","Point","Press"]'::jsonb, '"Pull"'::jsonb, 'PASS: Pull the pin, Aim at the base, Squeeze the handle, Sweep side to side.', 10, 6),
('d1000001-0001-0001-0001-000000000001', 'How many fire drills per year are required as a minimum in the UK?', 'multiple_choice', '["1","2","3","4"]'::jsonb, '"2"'::jsonb, 'UK fire safety law requires a minimum of 2 fire drills per year.', 10, 7),
('d1000001-0001-0001-0001-000000000001', 'RIDDOR stands for Reporting of Injuries, Diseases and Dangerous Occurrences Regulations.', 'true_false', '["True","False"]'::jsonb, '"True"'::jsonb, 'RIDDOR 2013 requires employers to report specified incidents to the HSE.', 10, 8),
('d1000001-0001-0001-0001-000000000001', 'How long must accident book records be kept?', 'multiple_choice', '["1 year","2 years","3 years","5 years"]'::jsonb, '"3 years"'::jsonb, 'Accident records must be retained for a minimum of 3 years.', 10, 9),
('d1000001-0001-0001-0001-000000000001', 'Which is the MOST effective control in the hierarchy of controls?', 'multiple_choice', '["PPE","Administrative controls","Elimination","Engineering controls"]'::jsonb, '"Elimination"'::jsonb, 'Elimination removes the hazard entirely — always the first option.', 10, 10);
INSERT INTO courses (id, title, description, template_style, estimated_duration_minutes, category_id, status, certificate_enabled, passing_score)
INSERT INTO course_modules (id, course_id, title, description, sort_order) VALUES
('a2000001-0002-0001-0002-000000000001', 'c2000001-aabb-bbcc-ccdd-000000000002', 'Food Safety Law & Personal Hygiene', 'UK food safety legislation and personal hygiene when handling food.', 1),
('a2000002-0002-0002-0002-000000000001', 'c2000001-aabb-bbcc-ccdd-000000000002', 'Food Contamination & Allergen Management', 'Types of food contamination and the 14 major food allergens under UK law.', 2),
('a2000003-0002-0003-0002-000000000001', 'c2000001-aabb-bbcc-ccdd-000000000002', 'Temperature Control, Cleaning & HACCP', 'Temperature control, cleaning procedures, and HACCP principles.', 3);
INSERT INTO course_lessons (id, module_id, title, sort_order, estimated_duration_minutes, content) VALUES
('b2010001-0002-0001-0001-000000000001', 'a2000001-0002-0001-0002-000000000001', 'UK Food Safety Legislation', 1, 5, '[{"type":"image","url":"/elearning/fs-course-hero.jpg","content":"Food Safety & Hygiene — Level 2 Training"},{"type":"heading","content":"UK Food Safety Law"},{"type":"paragraph","content":"Food safety in the UK is governed by a comprehensive legal framework designed to protect consumers. Anyone who handles, prepares, or sells food has a legal obligation to ensure it is safe to eat."},{"type":"subheading","content":"Key Legislation"},{"type":"bullet_points","items":["Food Safety Act 1990 — the primary UK food safety law. It is an offence to sell food that is injurious to health, unfit for human consumption, or so contaminated that it would be unreasonable to expect it to be eaten.","EC Regulation 852/2004 (retained in UK law) — general hygiene rules for all food business operators, including the requirement for HACCP-based procedures.","Food Safety and Hygiene (England) Regulations 2013 — transposes EU hygiene requirements into English law.","Food Information Regulations 2014 — requires food businesses to provide accurate allergen information.","The Food Standards Agency (FSA) — the independent government body responsible for food safety policy."]},{"type":"subheading","content":"The Food Hygiene Rating Scheme (FHRS)"},{"type":"paragraph","content":"Environmental Health Officers inspect food businesses and award a rating from 0 (urgent improvement) to 5 (very good). The inspection covers:"},{"type":"bullet_points","items":["How hygienically food is handled — preparation, cooking, reheating, cooling, storage","Physical condition of the premises — cleanliness, layout, lighting, ventilation, pest control","How the business manages food safety — HACCP documentation, staff training, temperature logs"]},{"type":"infobox","content":"It is a criminal offence to sell food that does not comply with food safety requirements. Penalties include unlimited fines, imprisonment of up to 2 years, and closure of the business."},{"type":"highlight","content":"Due diligence is your defence. You must demonstrate that you took all reasonable precautions and exercised all due diligence to avoid committing an offence."}]'::jsonb),
INSERT INTO course_assessments (id, course_id, title, passing_score, max_attempts, time_limit_minutes) VALUES
('d2000001-0002-0001-0001-000000000001', 'c2000001-aabb-bbcc-ccdd-000000000002', 'Food Safety & Hygiene Level 2 Assessment', 80, 3, 15);
INSERT INTO assessment_questions (assessment_id, question_text, question_type, options, correct_answer, explanation, points, sort_order) VALUES
('d2000001-0002-0001-0001-000000000001', 'What is the primary UK food safety legislation?', 'multiple_choice', '["Food Safety Act 1990","Health and Safety at Work Act 1974","Consumer Rights Act 2015","Environmental Protection Act 1990"]'::jsonb, '"Food Safety Act 1990"'::jsonb, 'The Food Safety Act 1990 is the primary legislation.', 10, 1),
('d2000001-0002-0001-0001-000000000001', 'What is the maximum legal temperature for chilled food in England?', 'multiple_choice', '["3°C","5°C","8°C","10°C"]'::jsonb, '"8°C"'::jsonb, 'Legal max is 8°C, best practice is 5°C or below.', 10, 2),
('d2000001-0002-0001-0001-000000000001', 'How many major food allergens must be declared under UK law?', 'multiple_choice', '["8","10","12","14"]'::jsonb, '"14"'::jsonb, 'UK law requires declaration of 14 major allergens.', 10, 3),
('d2000001-0002-0001-0001-000000000001', 'What minimum core temperature should food be cooked to?', 'multiple_choice', '["60°C for 10 minutes","65°C for 5 minutes","70°C for 2 minutes","75°C for 2 minutes"]'::jsonb, '"75°C for 2 minutes"'::jsonb, 'Food must reach 75°C for at least 2 minutes.', 10, 4),
('d2000001-0002-0001-0001-000000000001', 'You must not handle food for 48 hours after diarrhoea or vomiting.', 'true_false', '["True","False"]'::jsonb, '"True"'::jsonb, 'FSA/NHS require 48-hour exclusion after D&V.', 10, 5),
('d2000001-0002-0001-0001-000000000001', 'What does HACCP stand for?', 'multiple_choice', '["Health And Catering Control Procedures","Hazard Analysis and Critical Control Points","Hygiene Assessment and Contamination Control Plan","Health and Chemical Control Process"]'::jsonb, '"Hazard Analysis and Critical Control Points"'::jsonb, 'HACCP is a systematic food safety hazard approach.', 10, 6),
('d2000001-0002-0001-0001-000000000001', 'It is a criminal offence to sell food past its use-by date.', 'true_false', '["True","False"]'::jsonb, '"True"'::jsonb, 'A criminal offence under Food Safety Regulations.', 10, 7),
('d2000001-0002-0001-0001-000000000001', 'Where should raw meat be stored in a fridge?', 'multiple_choice', '["Top shelf","Any shelf if covered","Below ready-to-eat food","Next to dairy"]'::jsonb, '"Below ready-to-eat food"'::jsonb, 'Prevents drip contamination to ready-to-eat food.', 10, 8),
('d2000001-0002-0001-0001-000000000001', 'What is Natasha''s Law concerned with?', 'multiple_choice', '["Temperature control","Allergen labelling on PPDS food","Fire safety in kitchens","Waste disposal"]'::jsonb, '"Allergen labelling on PPDS food"'::jsonb, 'Requires full allergen labelling on PPDS food.', 10, 9),
('d2000001-0002-0001-0001-000000000001', 'How many steps are in the recommended cleaning process?', 'multiple_choice', '["3","4","5","6"]'::jsonb, '"6"'::jsonb, '6 stages: pre-clean, main clean, rinse, disinfect, final rinse, air dry.', 10, 10);
